import os
import boto3

def validate_document_fields(payload, config=None):
    config = config or {}
    region = config.get('region', 'us-east-1')
    client = boto3.client('textract', region_name=region)
    response = client.analyze_expense(
        Document={'Bytes': payload['content']},
        FeatureTypes=['INVOICES']
    )
    required_fields = config.get('required_fields', ['INVOICE_INVOICEID', 'INVOICE_VENDOR_NAME', 'INVOICE_INVOICEDATE', 'INVOICE_TOTALAMOUNT'])
    min_confidence = config.get('min_confidence', 0.8)
    expense_docs = response.get('ExpenseDocuments', [])
    extracted_fields = {}
    issues = []
    if expense_docs:
        doc = expense_docs[0]
        all_fields = doc.get('ExpenseFields', []) + doc.get('SummaryFields', [])
        for field in all_fields:
            field_name = field['Type']['Text']
            value_text = field['Value']['Text']
            conf = field['Confidence']
            extracted_fields[field_name] = {'value': value_text, 'confidence': conf}
        for field_name in required_fields:
            field_data = extracted_fields.get(field_name, {'confidence': 0.0, 'value': ''})
            if field_data['confidence'] < min_confidence:
                issues.append({'field': field_name, 'issue': 'low_confidence', 'confidence': field_data['confidence']})
            elif not field_data['value'].strip():
                issues.append({'field': field_name, 'issue': 'empty_value'})
    else:
        issues.append('No invoice documents found')
    result = {
        'valid': len(issues) == 0,
        'extracted_fields': extracted_fields,
        'issues': issues,
        'required_fields': required_fields,
        'min_confidence': min_confidence
    }
    return result
